import{_ as n,o as i,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ATLAS Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"projects/atlas-plugins/index.md","filePath":"projects/atlas-plugins/index.md","lastUpdated":1792684236000}'),a={name:"projects/atlas-plugins/index.md"};function l(s,e,o,u,d,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="atlas-plugins" tabindex="-1">ATLAS Plugins <a class="header-anchor" href="#atlas-plugins" aria-label="Permalink to &quot;ATLAS Plugins&quot;">​</a></h1><p>Diese Rubrik sammelt alles, was nicht den ATLAS-Kern selbst beschreibt, sondern installierbare Erweiterungen: Plugin-Verträge, Repository-Format, Veröffentlichung, Update-Verhalten und einzelne Plugin-Seiten.</p><div class="warning custom-block"><p class="custom-block-title">Entwicklungsstand</p><p>Die Plugin-Schnittstellen sind noch in Arbeit. Die Seiten dokumentieren den aktuellen ATLAS-Stand und werden mit stabileren Verträgen weiter ausgebaut.</p></div><h2 id="einstieg" tabindex="-1">Einstieg <a class="header-anchor" href="#einstieg" aria-label="Permalink to &quot;Einstieg&quot;">​</a></h2><ul><li><a href="./repository-format">Repository-Format</a>: Struktur einer <code>repository.json</code>, Pflichtfelder, ATLAS-Kennung und Beispiel.</li><li><a href="./plugin-template">Plugin-Vorlage</a>: Vorlage verwenden, Plugin anpassen, Paket bauen und veröffentlichen.</li><li><a href="./developers/">Plugin-Entwicklung</a>: Aufbau, Manifest, Runtime-Lebenszyklus und Veröffentlichung eigener Plugins.</li><li><a href="./gepruefte-plugins">Geprüfte Plugins</a>: kompakte Listen geprüfter und neuer ungeprüfter ATLAS-Plugins.</li><li><a href="./homeassistant-card-editor">Home Assistant Card Editor</a>: erstes offizielles ATLAS-Referenz-Plugin.</li><li><a href="./file-studio">ATLAS File Studio</a>: zweites unabhängiges ATLAS-Plugin für freigegebene Home-Assistant-Dateipfade.</li><li><a href="./icon-studio">ATLAS Icon Studio</a>: Iconsets verwalten, importieren und in Home Assistant speichern.</li><li><a href="./icon-library">ATLAS Icon Bibliothek</a>: Iconsets durchsuchen und vollständige Icon-Namen kopieren.</li><li><a href="./terminal">ATLAS Terminal</a>: authentifiziertes Browser-Terminal mit optionalem SSH-Ziel, Oh-My-Posh-Themes und serverseitig geladener Nerd Font.</li><li><a href="./automation-extractor">ATLAS Automation Exporter / Editor</a>: neues Plugin zum Analysieren, sicheren Sichern und Exportieren von Home-Assistant-Automationen.</li><li><a href="./demo-repository">Demo-Repository</a>: öffentliches Test-Repository für Administration, Hub und Installationsfluss.</li></ul><h2 id="plugin-version-sichern-und-wiederherstellen" tabindex="-1">Plugin-Version sichern und wiederherstellen <a class="header-anchor" href="#plugin-version-sichern-und-wiederherstellen" aria-label="Permalink to &quot;Plugin-Version sichern und wiederherstellen&quot;">​</a></h2><p>Ab ATLAS 0.1.304:</p><ol><li>Zuerst HA/ATLAS und eigene Plugin-Daten vollständig sichern.</li><li>Im Plugin-Manager ein vorhandenes Plugin-Paket importieren und die Vorschau mit alter/neuer Version und Fähigkeiten prüfen.</li><li>„Sichern und übernehmen“ erstellt vor dem Ersetzen eine serverseitige Rücksicherung. Ungeklärte Kompatibilität ausdrücklich prüfen; inkompatible Pakete bleiben gesperrt.</li><li>Für eine Rückkehr beim Plugin „Wiederherstellen“ wählen, Sicherung und Versionsrichtung prüfen und übernehmen. Auch der gerade installierte Stand wird dabei gesichert.</li></ol><p>Browserdaten und Datenformate werden damit nicht zurückgesetzt. Ein älteres Plugin muss zum vorhandenen Datenformat passen. <a href="./developers/compatibility#daten-erhalten-und-wiederherstellen">Grenzen und Sicherungspfad</a>. Die Oberfläche ist isoliert und auf Pi 5 und Proxmox mit Icon Bibliothek, File Studio und Terminal geprüft; andere Plugins und Datenmigrationen brauchen eigene Prüfungen.</p><h2 id="ziel" tabindex="-1">Ziel <a class="header-anchor" href="#ziel" aria-label="Permalink to &quot;Ziel&quot;">​</a></h2><p>ATLAS-Plugins sollen die Plattform erweitern, ohne Kernpakete direkt zu verändern. Dazu gehören Home-Assistant-nahe Werkzeuge, Card-Editoren, Diagnoseflächen, Renderer, Themes, Provider und später auch Community-Erweiterungen.</p><h2 id="lebenszyklus" tabindex="-1">Lebenszyklus <a class="header-anchor" href="#lebenszyklus" aria-label="Permalink to &quot;Lebenszyklus&quot;">​</a></h2><p>Ein Plugin soll nachvollziehbar installiert, geprüft, aktiviert, aktualisiert und entfernt werden können:</p><ol><li>Manifest lesen</li><li>Abhängigkeiten prüfen</li><li>Plugin registrieren</li><li>Services, Commands oder UI-Flächen bereitstellen</li><li>Aktivieren</li><li>Diagnose- und Statusdaten melden</li><li>Deaktivieren oder sauber entfernen</li></ol><h2 id="aktueller-technischer-anker" tabindex="-1">Aktueller technischer Anker <a class="header-anchor" href="#aktueller-technischer-anker" aria-label="Permalink to &quot;Aktueller technischer Anker&quot;">​</a></h2><p>Der aktuelle Einstieg ist der Runtime-Adapter. Ein <code>RuntimePlugin</code> kann mit <code>createRuntimeModuleFromPlugin()</code> in ein ATLAS-Runtime-Modul übersetzt werden. <code>RuntimePluginCatalog</code> stellt die Discovery-Fläche bereit, während die Administration Plugins sichtbar macht, Versionen vergleicht und lokale Installationen vorbereitet.</p><p>Der Plugin-Hub folgt inzwischen einer klaren Startregel: Wenn keine Plugins installiert sind, verweist er auf die Administration. Bei genau einem aktiven Plugin öffnet ATLAS dieses Plugin direkt. Bei zwei oder mehr aktiven Plugins zeigt ATLAS die Auswahlseite. Geplante oder deaktivierte Plugins dürfen sichtbar sein, werden aber nicht automatisch gestartet.</p><p>Der Plugin-Hub kann außerdem Seitenleisten-Einträge für Home Assistant vorbereiten. Der Dialog listet die aktuellen Plugins dynamisch, zeigt Name, URL, Version, Status und Icon-Vorschlag und kopiert wahlweise nur die URL oder einen fertigen <code>panel_iframe</code>-Block für die <code>configuration.yaml</code>. Die URL-Kopie ist für Home-Assistant-Dashboards vom Typ <code>Webseite</code> gedacht. Lange Fähigkeitslisten und Seitenleisten-URLs bleiben auf Plugin-Karten standardmäßig eingeklappt, damit der Hub auch mit vielen Plugins kompakt bleibt.</p><p>Card Editor, Administration und lokale Plugin-Assets werden im Add-on-Betrieb über ATLAS-App-Routen ausgeliefert. Dadurch bleiben Home-Assistant-Ingress-Basispfade in Hub- und Seitenleisten-URLs erhalten und andere Rechner im Netzwerk müssen die separaten Entwicklungsports nicht direkt erreichen.</p><h3 id="gemeinsame-spracheinstellung" tabindex="-1">Gemeinsame Spracheinstellung <a class="header-anchor" href="#gemeinsame-spracheinstellung" aria-label="Permalink to &quot;Gemeinsame Spracheinstellung&quot;">​</a></h3><p>Administration und Plugin-Hub unterstützen Deutsch, Englisch und Französisch. Eine in einer der beiden Oberflächen gewählte Sprache wird gespeichert und auch auf der anderen Oberfläche verwendet, selbst wenn beide über getrennte Ports laufen. Ein expliziter <code>language</code>-Parameter in einer Plugin-URL überschreibt diese Voreinstellung für den jeweiligen Aufruf.</p><p>Für ATLAS File Studio nutzt der Hub die Plugin-URL unter <code>/plugin-assets/file-studio/index.html</code> am ATLAS-App-Port beziehungsweise über die entsprechende Home-Assistant-Ingress-/Webseiten-Adresse. Diese URL wird auch dann vorbereitet, wenn ein älterer gespeicherter Plugin-Stand noch keine Start-URL enthält.</p><p>Neue lokale Plugins bekommen ebenfalls automatisch eine Start-URL, wenn ihr Plugin-Ordner eine <code>index.html</code> enthält und im Manifest kein <code>entry</code> gesetzt ist. ATLAS veröffentlicht dann <code>/plugin-assets/&lt;plugin-ordner&gt;/index.html</code>, sodass Nutzer direkt zwischen Hub und Home-Assistant-Seitenleiste wählen können.</p><h2 id="veroffentlichungsregeln" tabindex="-1">Veröffentlichungsregeln <a class="header-anchor" href="#veroffentlichungsregeln" aria-label="Permalink to &quot;Veröffentlichungsregeln&quot;">​</a></h2><p>Veröffentlichbare Plugins brauchen eindeutige Namen, klare Versionsangaben, dokumentierte Abhängigkeiten, sichere Demo- oder Fallback-Daten, nachvollziehbare Build-Artefakte und Hinweise für ATLAS, Home Assistant oder HACS-nahe Nutzung.</p><h2 id="automation-exporter-editor" tabindex="-1">Automation Exporter / Editor <a class="header-anchor" href="#automation-exporter-editor" aria-label="Permalink to &quot;Automation Exporter / Editor&quot;">​</a></h2><p>Der ATLAS Automation Exporter / Editor ergänzt die Plugin-Sammlung um Werkzeuge zum Erkennen von Automationen, Anzeigen ihrer Abhängigkeiten, Erstellen einer Sicherheitskopie beim Lesen und Exportieren einer Export-Version mit ID sowie einer bereinigten Import-Version ohne ID für den Home-Assistant-YAML-Editor.</p>',27)])])}const m=n(a,[["render",l]]);export{g as __pageData,m as default};
